      --muted: #a7b3c3;
      --line: rgba(255, 255, 255, 0.08);
      --accent: #7c5cff;
      --accent-2: #31d0aa;
      --accent-3: #ffb84d;
      --shadow: 0 24px 80px rgba(0, 0, 0, 0.35);
      --radius: 24px;
      --radius-sm: 16px;
      --max: 1200px;
    }

    * { box-sizing: border-box; }
    html { scroll-behavior: smooth; }
    body {
      margin: 0;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top left, rgba(124, 92, 255, 0.18), transparent 30%),
        radial-gradient(circle at top right, rgba(49, 208, 170, 0.12), transparent 32%),
        linear-gradient(180deg, #090c11 0%, #0b0f14 45%, #0a0d12 100%);
      color: var(--text);
      min-height: 100vh;
    }

    a { color: inherit; text-decoration: none; }
    button { font: inherit; }

    .container {
      width: min(100% - 32px, var(--max));
      margin: 0 auto;
    }

    .topbar {
      border-bottom: 1px solid var(--line);
      background: rgba(8, 11, 16, 0.72);
      backdrop-filter: blur(16px);
      position: sticky;
      top: 0;
      z-index: 20;
    }

    .topbar-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
      padding: 18px 0;
    }

    .brand {
      display: flex;
      align-items: center;
      gap: 12px;
      font-weight: 800;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .brand-mark {
      width: 38px;
      height: 38px;
      border-radius: 12px;
      background: linear-gradient(135deg, var(--accent), var(--accent-2));
      box-shadow: 0 10px 30px rgba(124, 92, 255, 0.35);
    }

    .nav {
      display: flex;
      align-items: center;
      gap: 20px;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .nav a:hover { color: var(--text); }

    .actions {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .search {
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 12px 16px;
      border: 1px solid var(--line);
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.03);
      color: var(--muted);
      min-width: 280px;
    }

    .search input {
      background: transparent;
      border: 0;
      outline: 0;
      color: var(--text);
      width: 100%;
    }

    .icon-btn, .primary-btn, .ghost-btn, .chip {
      border: 0;
      border-radius: 999px;
      cursor: pointer;
      transition: transform 180ms ease, background 180ms ease, border-color 180ms ease;
    }

    .icon-btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      width: 44px;
      height: 44px;
      background: rgba(255, 255, 255, 0.04);
      color: var(--text);
      border: 1px solid var(--line);
      position: relative;
    }

    .cart-badge {
      position: absolute;
      top: -4px;
      right: -4px;
      background: var(--accent-3);
      color: #131313;
      width: 20px;
      height: 20px;
      border-radius: 999px;
      display: grid;
      place-items: center;
      font-size: 0.72rem;
      font-weight: 700;
    }

    .hero {
      padding: 34px 0 24px;
    }

    .hero-grid {
      display: grid;
      grid-template-columns: 1.2fr 0.8fr;
      gap: 22px;
      align-items: stretch;
    }

    .panel {
      border: 1px solid var(--line);
      background: linear-gradient(180deg, rgba(255,255,255,0.06), rgba(255,255,255,0.02));
      box-shadow: var(--shadow);
      border-radius: var(--radius);
      overflow: hidden;
    }

    .hero-main {
      position: relative;
      min-height: 520px;
      padding: 34px;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      background:
        radial-gradient(circle at 80% 20%, rgba(124, 92, 255, 0.25), transparent 28%),
        radial-gradient(circle at 20% 90%, rgba(49, 208, 170, 0.15), transparent 30%),
        linear-gradient(145deg, rgba(17, 24, 34, 0.98), rgba(10, 13, 18, 0.98));
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      color: #d7ddf0;
      text-transform: uppercase;
      letter-spacing: 0.14em;
      font-size: 0.76rem;
      font-weight: 700;
    }

    .eyebrow::before {
      content: "";
      width: 38px;
      height: 1px;
      background: linear-gradient(90deg, var(--accent), var(--accent-2));
    }

    .hero h1 {
      margin: 14px 0 14px;
      font-size: clamp(3rem, 7vw, 5.6rem);
      line-height: 0.94;
      max-width: 10ch;
      letter-spacing: -0.06em;
    }

    .hero-copy {
      max-width: 580px;
      color: var(--muted);
      font-size: 1.05rem;
      line-height: 1.7;
    }

    .cta-row {
      display: flex;
      flex-wrap: wrap;
      gap: 12px;
      margin-top: 26px;
    }

    .primary-btn, .ghost-btn {
      padding: 14px 20px;
      font-weight: 700;
    }

    .primary-btn {
      background: linear-gradient(135deg, var(--accent), #9b7cff);
      color: white;
      box-shadow: 0 14px 30px rgba(124, 92, 255, 0.25);
    }

    .ghost-btn {
      background: rgba(255, 255, 255, 0.03);
      color: var(--text);
      border: 1px solid var(--line);
    }

    .hero-meta {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 12px;
      margin-top: 28px;
    }

    .stat {
      padding: 16px;
      border-radius: 18px;
      background: rgba(255, 255, 255, 0.04);
      border: 1px solid var(--line);
    }

    .stat strong {
      display: block;
      font-size: 1.2rem;
      margin-bottom: 6px;
    }

    .stat span { color: var(--muted); font-size: 0.9rem; }

    .hero-side {
      display: grid;
      gap: 22px;
    }

    .deal-card {
      padding: 24px;
      min-height: 250px;
      background:
        linear-gradient(180deg, rgba(255, 184, 77, 0.18), rgba(255, 255, 255, 0.03)),
        linear-gradient(145deg, rgba(18, 24, 34, 0.95), rgba(10, 14, 19, 0.95));
      position: relative;
    }

    .deal-pill {
      display: inline-flex;
      padding: 8px 12px;
      border-radius: 999px;
      background: rgba(255, 184, 77, 0.14);
      color: #ffd58a;
      font-size: 0.8rem;
      font-weight: 700;
      letter-spacing: 0.04em;
      text-transform: uppercase;
    }

    .deal-card h2, .editorial h2, .section-head h2 {
      margin: 14px 0 10px;
      font-size: 1.7rem;
      line-height: 1.1;
    }

    .deal-card p, .editorial p, .section-head p, .deal-timer {
      color: var(--muted);
      line-height: 1.6;
    }

    .deal-timer {
      margin-top: 18px;
      padding-top: 18px;
      border-top: 1px solid var(--line);
      display: flex;
      gap: 12px;
      flex-wrap: wrap;
      font-size: 0.92rem;
    }

    .timer-chip {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 10px 14px;
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.04);
      border: 1px solid var(--line);
      color: var(--text);
      min-width: 84px;
      justify-content: center;
    }

    .editorial {
      padding: 24px;
      background: linear-gradient(145deg, rgba(124, 92, 255, 0.12), rgba(255,255,255,0.03));
    }

    .section {
      padding: 24px 0 12px;
    }

    .section-head {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 16px;
      margin-bottom: 18px;
    }

    .section-head p {
      max-width: 620px;
      margin: 0;
    }

    .chips {
      display: flex;
      flex-wrap: wrap;
      gap: 10px;
    }

    .chip {
      padding: 10px 14px;
      background: rgba(255, 255, 255, 0.04);
      color: var(--muted);
      border: 1px solid var(--line);
    }

    .chip.active {
      background: rgba(124, 92, 255, 0.22);
      color: var(--text);
      border-color: rgba(124, 92, 255, 0.4);
    }

    .product-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 18px;
    }

    .product-card {
      padding: 14px;
      background: rgba(255, 255, 255, 0.03);
      border: 1px solid var(--line);
      border-radius: 22px;
      overflow: hidden;
      display: flex;
      flex-direction: column;
      gap: 14px;
    }

    .product-media {
      aspect-ratio: 1 / 1;
      border-radius: 18px;
      background: linear-gradient(145deg, rgba(255, 255, 255, 0.08), rgba(255, 255, 255, 0.02));
      position: relative;
      overflow: hidden;
    }

    .product-media::after {
      content: "";
      position: absolute;
      inset: 18% 14%;
      border-radius: 999px;
      background: radial-gradient(circle at 30% 30%, rgba(255,255,255,0.45), transparent 35%),
                  linear-gradient(145deg, rgba(124, 92, 255, 0.9), rgba(49, 208, 170, 0.85));
      filter: blur(0.2px);
      opacity: 0.9;
      transform: rotate(-14deg);
    }

    .product-media.alt-1::after { inset: 14% 18%; background: linear-gradient(145deg, rgba(255,184,77,0.95), rgba(124,92,255,0.82)); }
    .product-media.alt-2::after { inset: 20% 20%; background: linear-gradient(145deg, rgba(49,208,170,0.95), rgba(19, 122, 255, 0.78)); }
    .product-media.alt-3::after { inset: 16% 16%; background: linear-gradient(145deg, rgba(255, 112, 145, 0.92), rgba(124,92,255,0.76)); }

    .product-body h3 {
      margin: 0 0 8px;
      font-size: 1.02rem;
    }

    .product-body p {
      margin: 0;
      color: var(--muted);
      font-size: 0.94rem;
      line-height: 1.55;
    }

    .product-footer {
      margin-top: auto;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
    }

    .price {
      font-size: 1.05rem;
      font-weight: 800;
    }

    .rating {
      color: #ffd88c;
      font-size: 0.9rem;
      margin-top: 8px;
    }

    .mini-btn {
      padding: 10px 14px;
      border-radius: 999px;
      border: 1px solid rgba(124, 92, 255, 0.35);
      color: white;
      background: rgba(124, 92, 255, 0.16);
    }

    .story-grid {
      display: grid;
      grid-template-columns: 1fr 1fr 1fr;
      gap: 18px;
    }

    .story-card {
      padding: 18px;
      border-radius: 22px;
      border: 1px solid var(--line);
      background: rgba(255, 255, 255, 0.03);
    }

    .story-kicker {
      color: #c4cbdb;
      text-transform: uppercase;
      letter-spacing: 0.12em;
      font-size: 0.74rem;
      font-weight: 700;
    }

    .story-card h3 {
      margin: 12px 0 8px;
      font-size: 1.12rem;
    }

    .story-card p {
      margin: 0;
      color: var(--muted);
      line-height: 1.6;
    }

    .story-footer {
      margin-top: 16px;
      display: flex;
      justify-content: space-between;
      align-items: center;
      color: #dbe1ee;
      font-size: 0.92rem;
      border-top: 1px solid var(--line);
      padding-top: 14px;
    }

    .newsletter {
      margin: 26px 0 44px;
      padding: 24px;
      display: grid;
      grid-template-columns: 1.2fr 0.8fr;
      gap: 18px;
      align-items: center;
      background:
        radial-gradient(circle at right, rgba(49, 208, 170, 0.16), transparent 28%),
        linear-gradient(145deg, rgba(18, 24, 34, 0.98), rgba(10, 13, 19, 0.98));
    }

    .newsletter-form {
      display: flex;
      gap: 12px;
      align-items: center;
      justify-content: flex-end;
      flex-wrap: wrap;
    }

    .newsletter-form input {
      flex: 1 1 240px;
      min-height: 50px;
      border-radius: 999px;
      border: 1px solid var(--line);
      background: rgba(255, 255, 255, 0.04);
      color: var(--text);
      padding: 0 18px;
      outline: none;
    }

    .footer-note {
      padding: 0 0 28px;
      color: var(--muted);
      font-size: 0.9rem;
      text-align: center;
    }

    .toast {
      position: fixed;
      left: 50%;
      bottom: 22px;
      transform: translateX(-50%) translateY(18px);
      background: rgba(11, 15, 20, 0.92);
      color: white;
      border: 1px solid var(--line);
      box-shadow: var(--shadow);
      padding: 14px 18px;
      border-radius: 999px;
      opacity: 0;
      pointer-events: none;
      transition: opacity 180ms ease, transform 180ms ease;
      z-index: 40;
    }

    .toast.show {
      opacity: 1;
      transform: translateX(-50%) translateY(0);
    }

    @media (max-width: 1040px) {
      .hero-grid, .newsletter, .product-grid, .story-grid {
        grid-template-columns: 1fr;
      }

      .search { min-width: 0; width: 100%; }
      .topbar-inner { flex-wrap: wrap; }
      .nav { order: 3; width: 100%; justify-content: space-between; }
      .actions { margin-left: auto; }
    }

    @media (max-width: 720px) {
      .hero-main { padding: 24px; min-height: auto; }
      .hero h1 { font-size: clamp(2.7rem, 13vw, 4.2rem); }
      .hero-meta { grid-template-columns: 1fr; }
      .section-head, .newsletter-form { flex-direction: column; align-items: stretch; }
      .nav { gap: 12px; font-size: 0.88rem; flex-wrap: wrap; }
      .actions { width: 100%; justify-content: space-between; }
    }
  </style>
</head>
<body>
  <header class="topbar">
    <div class="container topbar-inner">
      <a class="brand" href="#home" aria-label="Noir Supply home">
        <span class="brand-mark" aria-hidden="true"></span>
        <span>Noir Supply</span>
      </a>

      <nav class="nav" aria-label="Primary">
        <a href="#featured">Featured</a>
        <a href="#deals">Deals</a>
        <a href="#stories">Editorial</a>
      </nav>

      <div class="actions">
        <label class="search" aria-label="Search products">
          <span aria-hidden="true">⌕</span>
          <input type="search" placeholder="Search jackets, sneakers, home..." />
