              <button class="primary-btn" type="button">Shop featured</button>
              <button class="ghost-btn" type="button">View lookbook</button>
            </div>
          </div>

          <div class="hero-meta" aria-label="Store highlights">
            <div class="stat">
              <strong>120+</strong>
              <span>New arrivals this week</span>
            </div>
            <div class="stat">
              <strong>24h</strong>
              <span>Fast dispatch on orders</span>
            </div>
            <div class="stat">
              <strong>4.9/5</strong>
