  <div class="toast" id="toast" role="status" aria-live="polite"></div>

  <p class="footer-note">Noir Supply — dark retail UI concept built with plain HTML, CSS, and vanilla JavaScript.</p>

  <script>
    const toast = document.getElementById('toast');
    const cartCount = document.getElementById('cartCount');
    const addButtons = document.querySelectorAll('.mini-btn');
    const subscribeForm = document.querySelector('.newsletter-form');
    const chips = document.querySelectorAll('.chip');
    const timerEls = {
      hours: document.getElementById('hours'),
      minutes: document.getElementById('minutes'),
      seconds: document.getElementById('seconds')
    };

    let cart = 2;
    let dealEndsAt = Date.now() + (12 * 60 * 60 + 48 * 60 + 19) * 1000;

    function showToast(message) {
      toast.textContent = message;
      toast.classList.add('show');
      clearTimeout(showToast._timer);
      showToast._timer = setTimeout(() => toast.classList.remove('show'), 2200);
    }

    function updateCart(delta = 1) {
      cart += delta;
      cartCount.textContent = cart;
    }

    function updateCountdown() {
      const remaining = Math.max(0, dealEndsAt - Date.now());
      const totalSeconds = Math.floor(remaining / 1000);
      const hours = Math.floor(totalSeconds / 3600);
      const minutes = Math.floor((totalSeconds % 3600) / 60);
      const seconds = totalSeconds % 60;

      timerEls.hours.textContent = `${String(hours).padStart(2, '0')}h`;
