       timerEls.minutes.textContent = `${String(minutes).padStart(2, '0')}m`;
       timerEls.seconds.textContent = `${String(seconds).padStart(2, '0')}s`;

       if (remaining === 0) {
         dealEndsAt = Date.now() + (12 * 60 * 60 + 48 * 60 + 19) * 1000;
         showToast('A new flash deal is live.');
